Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="flightAnim" class="active">⏸ Pause</button>
<label for="pathPosition">Bird position along path
  <input id="pathPosition" type="range" min="0" max="1" step="0.01" value="0">
</label>
<div style="margin-top:6px;font-weight:bold">Demo steps</div>
<button id="demo0">1 · Bird near the camera</button>
<button id="demo1">2 · Bird receding</button>
<button id="demo2">3 · Convergence to vanishing point</button>
<div style="font-size:10px;color:#555;margin-top:6px;line-height:1.45;max-width:180px">
  Drag the <b style="color:#c00">red sphere</b> to re-aim the 3D flight direction — the vanishing point on the image plane moves with it. Drag anywhere else to orbit; scroll to zoom. Click scene parts for explanations.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ─────────────────────────────────────────────────────
// O camera center      → SphereGeometry(0.08) #000000 at origin, label 'O'
// image plane          → PlaneGeometry(2.4,1.8) fill #bbbbbb @0.25, EdgesGeometry #555555, at z=-1.5
// flight path          → dashed Line #aaaaaa from START along DIR
// bird                 → ExtrudeGeometry(gull Shape, 0.04) #222222, scale 0.95; 6 ghosts @0.4 opacity + 1 solid animated
// velocity arrows      → ArrowHelper #ee0000 length 0.9 along DIR, one per bird, labeled V
// projection rays      → Line #00cc44 from O to every bird position (6 static + 1 animated)
// projected birds      → same gull ShapeGeometry #222222 laid ON the plane at each projection,
//                        scaled ∝ f/(-P.z) so they shrink toward the vanishing point
// projected dots       → SphereGeometry(0.024) #009933 on the plane
// image-velocity arrows→ short ArrowHelper #ee0000 between consecutive projections, shrinking toward VP
// vanishing point      → SphereGeometry(0.055) #000000 on the plane + label 'Vanishing point'
// direction handle     → SphereGeometry(0.1) #ee0000 + invisible hit proxy (drag to re-aim DIR)
// inset                → HTML <canvas> overlay (bottom-left) fed projected 2D coordinates

// ── constants / state (each declared exactly once) ───────────────────
const FOCAL = 1.5;
const PLANE_W = 2.4, PLANE_H = 1.8;
const PATH_LEN = 12;
const START = new THREE.Vector3(0.4, 0.3, -2);
let DIR = new THREE.Vector3(0.55, 0.25, -1).normalize();
const GTS = [0, 0.18, 0.36, 0.54, 0.72, 0.9];
const ORIGIN = new THREE.Vector3(0, 0, 0);
const ARROW_LEN = 0.9;
const BIRD_SCALE = 0.95;          // 3D birds — large enough to read like the source
const FLIGHT_DUR = 9;

let tCur = 0, flying = true, tween = null;

// scratch objects
const _tv1 = new THREE.Vector3(), _tv2 = new THREE.Vector3(), _tv3 = new THREE.Vector3();
const _tv4 = new THREE.Vector3(), _tv5 = new THREE.Vector3(), _tv6 = new THREE.Vector3();
const _m4 = new THREE.Matrix4();
const vp2 = new THREE.Vector2();
const curProj = new THREE.Vector2(), curProjAhead = new THREE.Vector2();
const HANDLE_R = START.clone().addScaledVector(DIR, 1.3).length();

// ── helpers ──────────────────────────────────────────────────────────
function pathPoint(t, out) {
  return (out || new THREE.Vector3()).copy(START).addScaledVector(DIR, t * PATH_LEN);
}
function projectPoint(P) {           // pinhole projection into plane-local coords
  const k = FOCAL / (-P.z);
  return new THREE.Vector2(P.x * k, P.y * k);
}
function planePoint(p2, zoff) {      // plane-local → world (z just in front of plane)
  return new THREE.Vector3(p2.x, p2.y, -FOCAL + zoff);
}
function setLine(line, a, b) {
  const p = line.geometry.attributes.position;
  p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z);
  p.needsUpdate = true;
  line.geometry.computeBoundingSphere();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
function orientBird(mesh, pos) {     // nose (local +y) along DIR, face toward O
  const yA = _tv4.copy(DIR);
  const zA = _tv5.subVectors(ORIGIN, pos).normalize();
  const xA = _tv6.crossVectors(yA, zA).normalize();
  const zA2 = _tv3.crossVectors(xA, yA).normalize();
  _m4.makeBasis(xA, yA, zA2);
  mesh.quaternion.setFromRotationMatrix(_m4);
}

// ── camera center O ──────────────────────────────────────────────────
const oMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000 })
);
scene.add(oMesh);
registerInteractive(oMesh, {
  title: 'Camera center O',
  tooltip: 'Pinhole camera center',
  body: 'The pinhole. Every green line is a ray from a bird position travelling straight through O; wherever that ray pierces the grey image plane is the bird\'s projected image.'
});

// ── image plane ──────────────────────────────────────────────────────
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(PLANE_W, PLANE_H),
  new THREE.MeshBasicMaterial({ color: 0xbbbbbb, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false })
);
planeMesh.position.set(0, 0, -FOCAL);
scene.add(planeMesh);
const planeEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(planeMesh.geometry),
  new THREE.LineBasicMaterial({ color: 0x555555 })
);
planeEdges.position.copy(planeMesh.position);
scene.add(planeEdges);
registerInteractive(planeMesh, {
  title: 'Image plane',
  tooltip: 'Projection surface, one focal length from O',
  body: 'Sits at distance f from O. A 3D point P projects to p = f·(P.x, P.y)/(−P.z). The farther a point (larger −P.z), the closer its projection crowds toward the vanishing point — perspective foreshortening.'
});

// ── flight path (dashed) ─────────────────────────────────────────────
const pathLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]),
  new THREE.LineDashedMaterial({ color: 0xaaaaaa, dashSize: 0.25, gapSize: 0.15 })
);
scene.add(pathLine);

// ── bird silhouette (gull glyph) ─────────────────────────────────────
function makeBirdShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.50, 0.05);
  s.quadraticCurveTo(-0.30, 0.30, -0.05, 0.10);   // left wing leading edge
  s.quadraticCurveTo(0.00, 0.17, 0.05, 0.10);     // head / beak bump
  s.quadraticCurveTo(0.30, 0.30, 0.50, 0.05);     // right wing leading edge
  s.quadraticCurveTo(0.26, 0.02, 0.07, -0.10);    // right trailing edge
  s.lineTo(0.03, -0.22);                          // tail right
  s.lineTo(-0.03, -0.22);                         // tail left
  s.quadraticCurveTo(-0.07, -0.10, -0.26, 0.02);  // left trailing edge
  s.closePath();
  return s;
}
const birdShape = makeBirdShape();
const birdGeom = new THREE.ExtrudeGeometry(birdShape, { depth: 0.04, bevelEnabled: false });
birdGeom.translate(0, 0, -0.02);
const birdFlatGeom = new THREE.ShapeGeometry(birdShape);   // for in-plane projections
const ghostMat = new THREE.MeshBasicMaterial({ color: 0x222222, transparent: true, opacity: 0.4 });
const solidMat = new THREE.MeshBasicMaterial({ color: 0x222222 });
const projBirdMat = new THREE.MeshBasicMaterial({ color: 0x222222, transparent: true, opacity: 0.55, side: THREE.DoubleSide });

const ghosts = GTS.map(() => {
  const m = new THREE.Mesh(birdGeom, ghostMat);
  m.scale.setScalar(BIRD_SCALE);
  scene.add(m);
  registerInteractive(m, {
    title: 'Constant 3D velocity',
    tooltip: 'Equal 3D steps, shrinking image steps',
    body: 'Every red V arrow has the same 3D length — the bird flies at constant velocity. But equal 3D steps project to ever-smaller image steps, so the projected positions bunch up toward the vanishing point.'
  });
  return m;
});
const bird = new THREE.Mesh(birdGeom, solidMat);
bird.scale.setScalar(BIRD_SCALE);
scene.add(bird);
registerInteractive(bird, {
  title: 'The flying bird',
  tooltip: 'Constant-velocity translation',
  body: 'The bird moves at constant 3D velocity, yet its projection races across the near part of the image and crawls as it approaches the vanishing point — image motion compresses with depth.'
});

// ── projected bird silhouettes ON the image plane ────────────────────
// Same gull glyph, laid flat in the plane, scale ∝ f/(-z) so the sequence of
// projected birds visibly shrinks toward the vanishing point, as in the source.
const projBirds = GTS.map(() => {
  const m = new THREE.Mesh(birdFlatGeom, projBirdMat);
  scene.add(m);
  registerInteractive(m, {
    title: 'Projected bird',
    tooltip: 'The bird\'s image shrinks with depth',
    body: 'The bird\'s silhouette as recorded on the image plane. Its size scales as f/(−z), so identical birds at equal 3D spacing produce ever-smaller images crowding the vanishing point.'
  });
  return m;
});
const animProjBird = new THREE.Mesh(birdFlatGeom, new THREE.MeshBasicMaterial({ color: 0x222222, side: THREE.DoubleSide }));
scene.add(animProjBird);

// ── red 3D velocity arrows (all equal length) ────────────────────────
const ghostArrows = GTS.map(() => {
  const a = new THREE.ArrowHelper(DIR, new THREE.Vector3(), ARROW_LEN, 0xee0000, 0.22, 0.13);
  scene.add(a);
  return a;
});
const birdArrow = new THREE.ArrowHelper(DIR, new THREE.Vector3(), ARROW_LEN, 0xee0000, 0.22, 0.13);
scene.add(birdArrow);

// ── green projection rays ────────────────────────────────────────────
const rayMat = new THREE.LineBasicMaterial({ color: 0x00cc44 });
const rays = GTS.map(() => {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), rayMat);
  scene.add(l);
  return l;
});
const animRay = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), rayMat.clone());
scene.add(animRay);

// ── projected dots + image-velocity arrows on the plane ─────────────
const projDots = GTS.map(() => {
  const dMesh = new THREE.Mesh(new THREE.SphereGeometry(0.024, 12, 8), new THREE.MeshBasicMaterial({ color: 0x009933 }));
  scene.add(dMesh);
  return dMesh;
});
const imgArrows = [];
for (let i = 0; i < GTS.length - 1; i++) {
  const a = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(), 0.1, 0xee0000, 0.05, 0.035);
  scene.add(a);
  imgArrows.push(a);
}
const animDot = new THREE.Mesh(new THREE.SphereGeometry(0.028, 12, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(animDot);
const animImgArrow = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(), 0.1, 0xee0000, 0.05, 0.035);
scene.add(animImgArrow);

// ── vanishing point ──────────────────────────────────────────────────
const vpDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(vpDot);
registerInteractive(vpDot, {
  title: 'Vanishing point (focus of expansion)',
  tooltip: 'Image of the flight direction',
  body: 'The image of the flight direction itself: the point a bird flying forever along V would asymptotically approach. Its position encodes the direction of translation, not the speed. Drag the red handle to move it.'
});

// ── drag handle for flight direction ────────────────────────────────
const handle = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 12), new THREE.MeshBasicMaterial({ color: 0xee0000 }));
scene.add(handle);
registerInteractive(handle, {
  title: 'Flight-direction handle',
  tooltip: 'Drag to re-aim the 3D velocity',
  body: 'Drag this red sphere to change the 3D flight direction. The whole path, the rays and the vanishing point move together — the vanishing point is the image of the direction itself.'
});
const hitProxy = new THREE.Mesh(
  new THREE.SphereGeometry(0.34, 8, 6),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
);
scene.add(hitProxy);

// ── labels (created before recomputeAll so anchors exist) ────────────
let vpLabel = null, vLabelStatic = null, vLabelAnim = null;

// ── rebuild everything from DIR ──────────────────────────────────────
function recomputeAll() {
  setLine(pathLine, START, pathPoint(1, _tv1));
  for (let i = 0; i < GTS.length; i++) {
    const P = pathPoint(GTS[i], _tv1);
    ghosts[i].position.copy(P); orientBird(ghosts[i], P);
    ghostArrows[i].position.copy(P); ghostArrows[i].setDirection(DIR);
    setLine(rays[i], ORIGIN, P);
    const pr = projectPoint(P);
    projDots[i].position.copy(planePoint(pr, 0.01));
    // projected bird: size ∝ f/(-z), lifted slightly off the plane toward O
    const pk = FOCAL / (-P.z);
    projBirds[i].position.copy(planePoint(pr, 0.015));
    projBirds[i].scale.setScalar(BIRD_SCALE * pk);
    if (i < GTS.length - 1) {
      const pr2 = projectPoint(pathPoint(GTS[i + 1], _tv2));
      const dl = pr2.clone().sub(pr);
      imgArrows[i].position.copy(planePoint(pr, 0.02));
      imgArrows[i].setDirection(new THREE.Vector3(dl.x, dl.y, 0).normalize());
      imgArrows[i].setLength(dl.length(), Math.min(0.06, dl.length() * 0.45), 0.04);
    }
  }
  vp2.set(FOCAL * DIR.x / (-DIR.z), FOCAL * DIR.y / (-DIR.z));
  vpDot.position.copy(planePoint(vp2, 0.025));
  handle.position.copy(START).addScaledVector(DIR, 1.3);
  hitProxy.position.copy(handle.position);
  if (vpLabel) vpLabel.pos.copy(vpDot.position);
  if (vLabelStatic) vLabelStatic.pos.copy(pathPoint(GTS[1], _tv1)).addScaledVector(DIR, 1.1);
  updateDynamic(tCur);
}

function updateDynamic(tc) {
  const P = pathPoint(tc, _tv1);
  bird.position.copy(P); orientBird(bird, P);
  birdArrow.position.copy(P); birdArrow.setDirection(DIR);
  setLine(animRay, ORIGIN, P);
  curProj.copy(projectPoint(P));
  animDot.position.copy(planePoint(curProj, 0.014));
  animProjBird.position.copy(planePoint(curProj, 0.015));
  animProjBird.scale.setScalar(BIRD_SCALE * FOCAL / (-P.z));
  curProjAhead.copy(projectPoint(pathPoint(Math.min(tc + 0.025, 1), _tv2)));
  const dl = curProjAhead.clone().sub(curProj);
  let len = dl.length() * 4;
  if (len > 1e-4 && tc < 0.999) {
    animImgArrow.visible = true;
    len = Math.min(len, 0.35);
    animImgArrow.position.copy(planePoint(curProj, 0.022));
    animImgArrow.setDirection(new THREE.Vector3(dl.x, dl.y, 0).normalize());
    animImgArrow.setLength(len, Math.min(0.06, len * 0.5), 0.04);
  } else animImgArrow.visible = false;
  if (vLabelAnim) vLabelAnim.pos.copy(P).addScaledVector(DIR, 1.1);
}

recomputeAll();

// ── camera (AFTER geometry) — near-frontal composition like the source ──
// Source reads as: O bottom-left, plane standing nearly face-on, path receding
// right-and-up. A low elevation and an azimuth close to head-on (90°) keep the
// ray-fan-through-plane structure immediately legible while still showing depth.
setCameraView({ projection: 'perspective', azimuthDeg: 74, elevationDeg: 12, rollDeg: 0, heightFraction: 0.62 });

// ── labels ───────────────────────────────────────────────────────────
addLabel('<b>O</b>', oMesh.position, { offset: [-18, 18], fontSize: '16px' });
vpLabel = addLabel('<b>Vanishing point</b>', vpDot.position, { offset: [30, 24], fontSize: '15px' });
vLabelStatic = addLabel('<i><b>V</b></i>', pathPoint(GTS[1], new THREE.Vector3()).addScaledVector(DIR, 1.1), { offset: [0, -16], fontSize: '15px' });
vLabelAnim = addLabel('<i><b>V</b></i>', pathPoint(0, new THREE.Vector3()), { offset: [0, -16], fontSize: '15px' });
addLabel('image plane', new THREE.Vector3(-1.05, 0.98, -FOCAL), { color: '#555', fontSize: '11px' });
recomputeAll();   // refresh label anchor positions

// ── 2D image-plane inset (HTML overlay fed projected coordinates) ────
const inset = document.createElement('canvas');
inset.width = 240; inset.height = 180;
inset.style.cssText = 'position:absolute;left:8px;bottom:8px;border:1px solid #999;background:#fff;z-index:5;pointer-events:none;border-radius:3px;';
_stage.appendChild(inset);
const ictx = inset.getContext('2d');
function insetArrow(x1, y1, x2, y2, color) {
  ictx.strokeStyle = color; ictx.fillStyle = color; ictx.lineWidth = 1.5;
  ictx.beginPath(); ictx.moveTo(x1, y1); ictx.lineTo(x2, y2); ictx.stroke();
  const ang = Math.atan2(y2 - y1, x2 - x1);
  ictx.beginPath();
  ictx.moveTo(x2, y2);
  ictx.lineTo(x2 - 6 * Math.cos(ang - 0.4), y2 - 6 * Math.sin(ang - 0.4));
  ictx.lineTo(x2 - 6 * Math.cos(ang + 0.4), y2 - 6 * Math.sin(ang + 0.4));
  ictx.closePath(); ictx.fill();
}
// little gull glyph for the inset, scaled/rotated at (x,y) facing direction ang
function insetBird(x, y, s, ang) {
  ictx.save();
  ictx.translate(x, y); ictx.rotate(ang); ictx.scale(s, s);
  ictx.fillStyle = '#222';
  ictx.beginPath();
  ictx.moveTo(0, 0);
  ictx.quadraticCurveTo(-4, -6, -9, -5);
  ictx.quadraticCurveTo(-4, -1, 0, 1);
  ictx.quadraticCurveTo(4, -1, 9, -5);
  ictx.quadraticCurveTo(4, -6, 0, 0);
  ictx.closePath(); ictx.fill();
  ictx.restore();
}
function drawInset() {
  const w = inset.width, h = inset.height, m = 16;
  const X = px => m + (px + PLANE_W / 2) / PLANE_W * (w - 2 * m);
  const Y = py => h - m - (py + PLANE_H / 2) / PLANE_H * (h - 2 * m);
  ictx.clearRect(0, 0, w, h);
  ictx.fillStyle = '#fff'; ictx.fillRect(0, 0, w, h);
  ictx.strokeStyle = '#888'; ictx.lineWidth = 1;
  ictx.strokeRect(X(-PLANE_W / 2), Y(PLANE_H / 2), X(PLANE_W / 2) - X(-PLANE_W / 2), Y(-PLANE_H / 2) - Y(PLANE_H / 2));
  ictx.fillStyle = '#333'; ictx.font = '10px sans-serif';
  ictx.fillText('image-plane view', m + 2, 11);
  // shrinking projected bird silhouettes along the projected path
  for (let i = 0; i < GTS.length; i++) {
    const P = pathPoint(GTS[i], _tv1);
    const p = projectPoint(P);
    const s = 26 * FOCAL / (-P.z);            // same f/(-z) shrink as the 3D plane birds
    const ang = Math.atan2(-(vp2.y - p.y), vp2.x - p.x) + Math.PI / 2;
    insetBird(X(p.x), Y(p.y), Math.min(s, 1.6), ang);
  }
  for (let i = 0; i < GTS.length - 1; i++) {
    const a = projectPoint(pathPoint(GTS[i], _tv1));
    const b = projectPoint(pathPoint(GTS[i + 1], _tv2));
    insetArrow(X(a.x), Y(a.y), X(b.x), Y(b.y), '#ee0000');
  }
  ictx.fillStyle = '#000';
  ictx.beginPath(); ictx.arc(X(vp2.x), Y(vp2.y), 4, 0, 7); ictx.fill();
  ictx.font = '9px sans-serif';
  ictx.fillText('vanishing point', Math.min(X(vp2.x) + 6, w - 78), Y(vp2.y) + 3);
  ictx.beginPath(); ictx.arc(X(curProj.x), Y(curProj.y), 4, 0, 7); ictx.fill();
  if (animImgArrow.visible) {
    insetArrow(X(curProj.x), Y(curProj.y), X(curProjAhead.x), Y(curProjAhead.y), '#ee0000');
  }
}

// ── controls: fly animation + slider + demo steps ────────────────────
const flyBtn = document.getElementById('flightAnim');
const slider = document.getElementById('pathPosition');
function syncFlyBtn() {
  flyBtn.textContent = flying ? '⏸ Pause' : '▶ Fly';
  flyBtn.classList.toggle('active', flying);
}
flyBtn.addEventListener('click', () => { flying = !flying; tween = null; syncFlyBtn(); });
slider.addEventListener('pointerdown', () => { flying = false; tween = null; syncFlyBtn(); });
slider.addEventListener('input', () => { tCur = parseFloat(slider.value); updateDynamic(tCur); });
syncFlyBtn();

const demoSteps = [
  { title: 'Bird near the camera', t: 0.15, narration: 'With the bird close to O, its projection sits far from the vanishing point and the image-velocity arrow is long — nearby motion produces large image motion.' },
  { title: 'Bird receding', t: 0.5, narration: 'Halfway along the path the projected bird has moved much less than the 3D bird; the image-velocity arrow has clearly shortened.' },
  { title: 'Convergence to the vanishing point', t: 0.95, narration: 'Far along the path the projected bird all but sits on the vanishing point and the image velocity approaches zero — equal 3D steps produce vanishingly small image steps.' }
];
function goToStep(i) {
  const s = demoSteps[i];
  flying = false; syncFlyBtn();
  tween = { from: tCur, to: s.t, t0: performance.now(), dur: 1800 };
  showPopup(s.title, s.narration);
}
window.goToStep = goToStep;
['demo0', 'demo1', 'demo2'].forEach((id, i) => document.getElementById(id).addEventListener('click', () => goToStep(i)));

// ── drag: re-aim flight direction ────────────────────────────────────
const rc = new THREE.Raycaster(), ptr = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 2);
let dragging = false;
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ptr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
function farSphereHit(ray, R, out) {
  const o = ray.origin, di = ray.direction;
  const b = o.dot(di), c = o.lengthSq() - R * R;
  const disc = b * b - c; if (disc < 0) return null;
  const t2 = -b + Math.sqrt(disc);
  if (t2 <= 0) return null;
  return ray.at(t2, out);
}
canvas.addEventListener('pointerdown', (e) => {
  setPtr(e); rc.setFromCamera(ptr, camera);
  if (rc.intersectObject(hitProxy, false).length) { dragging = true; controls.enabled = false; }
});
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setPtr(e); rc.setFromCamera(ptr, camera);
  let h = farSphereHit(rc.ray, HANDLE_R, _tv1);
  if (!h) h = rc.ray.intersectPlane(dragPlane, _tv1);
  if (!h || h.z > -0.3) return;
  let a = h.x / (-h.z), b = h.y / (-h.z);
  a = Math.max(-0.7, Math.min(0.7, a));
  b = Math.max(-0.5, Math.min(0.5, b));
  DIR.set(a, b, -1).normalize();
  recomputeAll();
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

// ── per-frame update loop ────────────────────────────────────────────
let lastNow = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - lastNow) / 1000); lastNow = now;
  if (tween) {
    const u = Math.min(1, (now - tween.t0) / tween.dur);
    const k = u * u * (3 - 2 * u);
    tCur = tween.from + (tween.to - tween.from) * k;
    slider.value = tCur;
    if (u >= 1) tween = null;
  } else if (flying) {
    tCur = (tCur + dt / FLIGHT_DUR) % 1;
    slider.value = tCur;
  }
  updateDynamic(tCur);
  drawInset();
}
requestAnimationFrame(tick);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
